export default function Page() {
  return (
    <LegacyPage
      css={["/werterhalt.css","/partial.css"]}
      html={pageHtml}
      scripts={["/werterhalt.js","/script.js"]}
      shell={true}
    >
      <style dangerouslySetInnerHTML={{ __html: forcedPropertyThemeCss }} data-property-theme-force />
    </LegacyPage>
  );
}
